-- =====================================================================
-- BANK TRADING PLATFORM — SEED DATA
-- =====================================================================
-- Run AFTER schema.sql.
-- Passwords are intentionally omitted here (empty string placeholder).
-- Before going to production, replace every password_hash with a real
-- Argon2id encoded string generated by the Java application.
--
-- Insertion order matters because of FK constraints:
--   roles → permissions → role_permissions
--   → users (admin) → traders → clients → wallets
-- The trigger trg_users_enforce_creator blocks admin-role inserts unless
-- the creator is already an ADMIN, so we temporarily bypass it for the
-- seed admin, then re-enable checks for all subsequent rows.
-- =====================================================================

USE trading_platform;


-- =====================================================================
-- ROLES
-- =====================================================================

INSERT INTO roles (role_name) VALUES
    ('ADMIN'),    -- role_id = 1
    ('TRADER'),   -- role_id = 2
    ('CLIENT');   -- role_id = 3


-- =====================================================================
-- PERMISSIONS
-- =====================================================================

INSERT INTO permissions (permission_name, description) VALUES
    ('MANAGE_USERS',       'Create, update, and suspend trader and client accounts'),
    ('MANAGE_INSTRUMENTS', 'Add, edit, and delist tradable instruments'),
    ('MANAGE_RULES',       'Configure trading limits and risk parameters'),
    ('VIEW_ALL_TRADES',    'View every trade executed on the platform'),
    ('PLACE_ORDER',        'Submit buy/sell orders on behalf of a client'),
    ('CANCEL_ORDER',       'Cancel a pending or partially-filled order'),
    ('VIEW_OWN_PORTFOLIO', 'View own holdings, wallet balance, and trade history');


-- =====================================================================
-- ROLE → PERMISSION MAPPING
-- =====================================================================

-- ADMIN: platform management (no trading permissions by design)
INSERT INTO role_permissions (role_id, permission_id)
SELECT 1, permission_id
FROM   permissions
WHERE  permission_name IN (
    'MANAGE_USERS',
    'MANAGE_INSTRUMENTS',
    'MANAGE_RULES',
    'VIEW_ALL_TRADES'
);

-- TRADER: order execution only
INSERT INTO role_permissions (role_id, permission_id)
SELECT 2, permission_id
FROM   permissions
WHERE  permission_name IN (
    'PLACE_ORDER',
    'CANCEL_ORDER'
);

-- CLIENT: read-only self-service view
INSERT INTO role_permissions (role_id, permission_id)
SELECT 3, permission_id
FROM   permissions
WHERE  permission_name = 'VIEW_OWN_PORTFOLIO';


-- =====================================================================
-- SYSTEM ADMIN (seed — the only row allowed to have created_by = NULL)
-- =====================================================================
-- The trigger trg_users_enforce_creator permits NULL created_by only
-- when the users table is completely empty, which it is at this point.

INSERT INTO users (username, email, password_hash, password_algo, role_id, status, created_by)
VALUES (
    'sysadmin',
    'sysadmin@bank.local',
    -- TODO: replace with a real Argon2id hash from the Java app before production
    '$argon2id$v=19$m=65536,t=3,p=4$REPLACE_SALT$REPLACE_HASH',
    'argon2id',
    1,           -- ADMIN
    'ACTIVE',
    NULL         -- no creator; this is the bootstrap account
);

-- Capture the admin's user_id for use in subsequent inserts.
SET @admin_id = LAST_INSERT_ID();


-- =====================================================================
-- TRADERS  (5 accounts, created by the system admin)
-- =====================================================================

INSERT INTO users (username, email, password_hash, password_algo, role_id, status, created_by)
