    ('trader_rohan',   'rohan.verma@bank.local',    '', 'argon2id', 2, 'ACTIVE', @admin_id),
    ('trader_anika',   'anika.gupta@bank.local',    '', 'argon2id', 2, 'ACTIVE', @admin_id),
    ('trader_vikram',  'vikram.nair@bank.local',    '', 'argon2id', 2, 'ACTIVE', @admin_id);

